CREATE TABLE `customer_quote_versions` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`quote_number` text NOT NULL,`version` integer NOT NULL,`customer_id` integer NOT NULL,`property_id` integer NOT NULL,`handoff_id` integer NOT NULL,`status` text DEFAULT 'issued' NOT NULL,`currency` text DEFAULT 'USD' NOT NULL,`subtotal` real NOT NULL,`discount_amount` real DEFAULT 0 NOT NULL,`tax_amount` real DEFAULT 0 NOT NULL,`installation_fee` real DEFAULT 0 NOT NULL,`deposit_required` real DEFAULT 0 NOT NULL,`total` real NOT NULL,`terms` text DEFAULT '' NOT NULL,`valid_until` text NOT NULL,`rendering_urls_json` text DEFAULT '[]' NOT NULL,`options_json` text DEFAULT '[]' NOT NULL,`selected_option_ids_json` text DEFAULT '[]' NOT NULL,`source_snapshot_json` text NOT NULL,`document_sha256` text NOT NULL,`created_by` integer NOT NULL,`created_at` text DEFAULT CURRENT_TIMESTAMP NOT NULL,`signed_at` text);
CREATE UNIQUE INDEX `customer_quote_versions_number_version_unique` ON `customer_quote_versions` (`quote_number`,`version`); CREATE INDEX `customer_quote_versions_handoff_idx` ON `customer_quote_versions` (`handoff_id`); CREATE INDEX `customer_quote_versions_property_idx` ON `customer_quote_versions` (`property_id`);
CREATE TABLE `customer_quote_signatures` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,`quote_version_id` integer NOT NULL,`user_id` integer NOT NULL,`printed_name` text NOT NULL,`timezone` text NOT NULL,`disclaimer_version` text NOT NULL,`signature_text` text NOT NULL,`signed_document_sha256` text NOT NULL,`ip_address_hash` text NOT NULL,`user_agent_hash` text NOT NULL,`idempotency_key` text NOT NULL,`signed_at` text NOT NULL);
CREATE UNIQUE INDEX `customer_quote_signatures_quote_version_id_unique` ON `customer_quote_signatures` (`quote_version_id`); CREATE UNIQUE INDEX `customer_quote_signatures_idempotency_key_unique` ON `customer_quote_signatures` (`idempotency_key`); CREATE INDEX `customer_quote_signatures_user_idx` ON `customer_quote_signatures` (`user_id`);
